using System;using System.Drawing;using System.Windows.Forms;using AshkanJobCenter.Core;using AshkanJobCenter.Data;
namespace AshkanJobCenter.UI{public class HiringInsightsPage:UserControl{FlowLayoutPanel cards;DataGridView funnel,aging;public HiringInsightsPage(){BackColor=Theme.Background;AutoScroll=true;cards=new FlowLayoutPanel{Dock=DockStyle.Top,Height=125,WrapContents=false,Padding=new Padding(0,8,0,8)};funnel=Ui.Grid();funnel.Dock=DockStyle.Top;funnel.Height=250;aging=Ui.Grid();aging.Dock=DockStyle.Fill;Controls.Add(aging);Controls.Add(funnel);Controls.Add(cards);LoadData();}Panel Card(string title,string value){var p=new Panel{Width=220,Height=96,BackColor=Theme.Surface,Margin=new Padding(0,0,14,0),Padding=new Padding(14)};var t=Ui.Label(title,9);t.ForeColor=Theme.Muted;t.Dock=DockStyle.Top;var v=Ui.Label(value,20,true);v.Dock=DockStyle.Fill;p.Controls.Add(v);p.Controls.Add(t);return p;}string S(object o){return Convert.ToString(o??0);}void LoadData(){cards.Controls.Clear();cards.Controls.Add(Card(L.Fa?"موقعیت‌های باز":"Open jobs",S(Database.Scalar("SELECT COUNT(*) FROM Jobs WHERE Status='Open'"))));cards.Controls.Add(Card(L.Fa?"کاندیداهای فعال":"Active candidates",S(Database.Scalar("SELECT COUNT(*) FROM Candidates WHERE Status<>'Archived'"))));cards.Controls.Add(Card(L.Fa?"مصاحبه‌های پیش‌رو":"Upcoming interviews",S(Database.Scalar("SELECT COUNT(*) FROM Interviews WHERE ScheduledAt>=SYSDATETIME() AND Status='Scheduled'"))));cards.Controls.Add(Card(L.Fa?"پیشنهادهای باز":"Open offers",S(Database.Scalar("SELECT COUNT(*) FROM Offers WHERE Status IN ('Draft','Pending','Sent')"))));funnel.DataSource=Database.Query("SELECT Stage,COUNT(*) AS Candidates,CAST(AVG(CAST(ISNULL(Score,0) AS FLOAT)) AS DECIMAL(10,1)) AS AvgScore FROM Applications GROUP BY Stage ORDER BY COUNT(*) DESC");aging.DataSource=Database.Query("SELECT TOP 30 a.Id,c.FullName,j.Title,a.Stage,DATEDIFF(day,a.AppliedAt,SYSDATETIME()) AS DaysInProcess,a.Score FROM Applications a INNER JOIN Candidates c ON c.Id=a.CandidateId INNER JOIN Jobs j ON j.Id=a.JobId WHERE a.Stage NOT IN ('Hired','Rejected') ORDER BY DaysInProcess DESC");}}}
